  function counts(t,compact=false){let live=0,done=0,remaining=0,unlinked=0;for(const p of list(t?.starters)){const g=games().find(g=>String(g.id)===String(p.gameId));if(g?.state==='in')live++;else if(g?.state==='post')done++;else if(g?.state==='pre')remaining++;else unlinked++;}const parts=[];if(live)parts.push(`${live} ${compact?'live':'playing on this slate'}`);if(remaining)parts.push(`${remaining} ${compact?'upcoming':'yet to play on this slate'}`);if(done)parts.push(`${done} ${compact?'final':'finished on this slate'}`);if(unlinked)parts.push(`${unlinked} ${compact?'not on this slate':'not linked to this slate'}`);return parts.join(' · ')||'See player rows for game status';}
